    role: r.hasIpcChannel && /forks/.test(r.argv[0]) ? 'vitest-fork-worker' : /vitest/.test(r.argv[0]) ? 'vitest-main' : 'other',
    version: r.version,
    execPath: r.execPath,
    cwd: r.cwd,
    cwdRoot: r.cwdRoot,
