    ['realpathSync(dataDir)', 'realpathSync.native(dataDir)'],
    ['realpathSync(path)', 'realpathSync.native(path)'],
  ];
  const count = (s, needle) => s.split(needle).length - 1;
  const rewritten = sites.reduce((s, [from, to]) => s.split(from).join(to), baseText);
  const tokens = ['expect(', 'toBe(', 'toHaveBeenCalledExactlyOnceWith(', 'toHaveBeenCalledTimes(',
    'toHaveLength(', 'toMatchObject(', 'toEqual(', 'toHaveBeenCalledWith(', '.skip', '.only', '.todo',
    'retry', 'timeout', 'chdir', 'vi.mock', 'toLowerCase('];
  return {
    siteCountsBaseline: sites.map(([from, to]) => ({ from, inBaseline: count(baseText, from), toInBaseline: count(baseText, to) })),
    siteCountsCandidate: sites.map(([from, to]) => ({ from, inCandidate: count(candText, from), toInCandidate: count(candText, to) })),
    whitespaceInsensitiveEqualAfterTwoSiteRewrite: strip(rewritten) === strip(candText),
    whitespaceInsensitiveEqualWithoutRewrite: strip(baseText) === strip(candText),
    tokenCounts: Object.fromEntries(tokens.map((t) => [t, { baseline: count(baseText, t), candidate: count(candText, t) }])),
  };
}

