const ident = (p, follow = false) => {
  const s = follow ? fs.statSync(p, { bigint: true }) : fs.lstatSync(p, { bigint: true });
  return {
    dev: String(s.dev),
    ino: String(s.ino),
    birthtimeNs: String(s.birthtimeNs),
    isSymbolicLink: s.isSymbolicLink(),
    isDirectory: s.isDirectory(),
