    id: 's4-candidate-e630-junction-g-temp-engine-fixed-temp-template-tapped',
    criterion: 4,
    fixture: 'corrected',
    temp: 'alias',
    name: THREE_CASE,
    tap: true,
  },
  s5a: {
    id: 's5a-candidate-e630-c-long-temp-adapter-mixed-tapped',
    criterion: 5,
    fixture: 'corrected',
    temp: 'clong',
