const dev = (p) => String(fs.statSync(p, { bigint: true }).dev);
const capacity = (p) => {
  const s = fs.statfsSync(p, { bigint: true });
  return {
    path: p,
    bsize: String(s.bsize),
    freeBytes: String(s.bavail * s.bsize),
    totalBytes: String(s.blocks * s.bsize),
