      const full = path.join(p, name);
      const r = rel ? rel + '\\' + name : name;
      const s = fs.lstatSync(full);
      const type = s.isSymbolicLink()
        ? 'link'
        : s.isDirectory()
          ? 'dir'
          : s.isFile()
            ? 'file'
            : 'other';
      out.push({ rel: r, type, bytes: s.isFile() ? s.size : 0 });
